import 'package:cloud_firestore/cloud_firestore.dart';
import 'attachment_model.dart';
enum MessageType { text, image, file, voice, system }
enum MessageStatus { sending, sent, delivered, read, failed }
class MessageModel { const MessageModel({required this.id,required this.conversationId,required this.senderId,required this.createdAt,required this.type,this.receiverId,this.text='',this.attachment,this.replyToMessageId,this.status=MessageStatus.sent,this.isDeleted=false}); final String id,conversationId,senderId,text; final String? receiverId,replyToMessageId; final MessageType type; final AttachmentModel? attachment; final MessageStatus status; final DateTime createdAt; final bool isDeleted; factory MessageModel.fromFirestore(DocumentSnapshot<Map<String,dynamic>> doc)=>MessageModel.fromMap(doc.id,doc.data()); factory MessageModel.fromMap(String id,Map<String,dynamic> map)=>MessageModel(id:id,conversationId:map['conversationId'] as String? ?? '',senderId:map['senderId'] as String? ?? '',receiverId:map['receiverId'] as String?,text:map['text'] as String? ?? '',type:MessageType.values.firstWhere((item)=>item.name==map['type'],orElse:()=>MessageType.text),attachment:map['attachment']==null?null:AttachmentModel.fromMap(Map<String,dynamic>.from(map['attachment'] as Map)),replyToMessageId:map['replyToMessageId'] as String?,status:MessageStatus.values.firstWhere((item)=>item.name==map['status'],orElse:()=>MessageStatus.sent),createdAt:(map['createdAt'] as Timestamp?)?.toDate() ?? DateTime.now(),isDeleted:map['isDeleted'] as bool? ?? false); Map<String,Object?> toMap()=>{'conversationId':conversationId,'senderId':senderId,'receiverId':receiverId,'text':text,'type':type.name,'attachment':attachment?.toMap(),'replyToMessageId':replyToMessageId,'status':status.name,'createdAt':Timestamp.fromDate(createdAt),'isDeleted':isDeleted,'updatedAt':FieldValue.serverTimestamp()}; }
